from pathlib import Path
import json
import sqlite3
from datetime import datetime

import joblib
import pandas as pd
import plotly.express as px
import streamlit as st

# ------------------------------------------------------------
# AI-POWERED FINANCIAL FRAUD DETECTION - PORTFOLIO DEMO
# Uses the trained model and threshold generated by main.py.
# The investigation narrative below is rule-based, not an LLM.
# ------------------------------------------------------------

st.set_page_config(
    page_title="Financial Fraud Detection",
    page_icon="🛡️",
    layout="wide",
)

PROJECT_DIR = Path(__file__).resolve().parent
DATA_DIR = PROJECT_DIR / "data"
OUTPUT_DIR = PROJECT_DIR / "outputs"
DB_PATH = OUTPUT_DIR / "fraud_alerts.db"
MODEL_PATH = OUTPUT_DIR / "fraud_model.joblib"
CONFIG_PATH = OUTPUT_DIR / "fraud_model_config.json"

FEATURES = ["step", "type", "amount", "oldbalanceOrg", "oldbalanceDest"]
TRANSACTION_TYPES = ["PAYMENT", "TRANSFER", "CASH_OUT", "CASH_IN", "DEBIT"]


def init_db():
    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
    with sqlite3.connect(DB_PATH) as conn:
        conn.execute("""
            CREATE TABLE IF NOT EXISTS fraud_alerts (
                alert_id INTEGER PRIMARY KEY AUTOINCREMENT,
                created_at TEXT NOT NULL,
                step INTEGER NOT NULL,
                transaction_type TEXT NOT NULL,
                amount REAL NOT NULL,
                oldbalance_org REAL NOT NULL,
                oldbalance_dest REAL NOT NULL,
                fraud_probability REAL NOT NULL,
                threshold REAL NOT NULL,
                risk_level TEXT NOT NULL,
                decision TEXT NOT NULL
            )
        """)
        conn.commit()


@st.cache_resource
def load_model_and_config():
    if not MODEL_PATH.exists():
        return None, None
    model = joblib.load(MODEL_PATH)
    config = {}
    if CONFIG_PATH.exists():
        with open(CONFIG_PATH, "r", encoding="utf-8") as f:
            config = json.load(f)
    return model, config


@st.cache_data(show_spinner="Reading transaction data for dashboard...")
def load_dashboard_data():
    csv_files = sorted(DATA_DIR.glob("*.csv"))
    if not csv_files:
        return None, None, None

    # Read only the columns needed for summary metrics.
    usecols = ["step", "type", "amount", "isFraud"]
    chunks = []
    for chunk in pd.read_csv(csv_files[0], usecols=usecols, chunksize=250_000):
        chunks.append(chunk)

    data = pd.concat(chunks, ignore_index=True)
    type_summary = (
        data.groupby("type", as_index=False)
        .agg(
            transactions=("isFraud", "size"),
            fraud_cases=("isFraud", "sum"),
            transaction_amount=("amount", "sum"),
        )
    )
    type_summary["fraud_rate_pct"] = (
        type_summary["fraud_cases"] / type_summary["transactions"] * 100
    )
    time_summary = (
        data.groupby("step", as_index=False)
        .agg(transactions=("isFraud", "size"), fraud_cases=("isFraud", "sum"))
    )
    return data, type_summary, time_summary


def money(value):
    return f"₹{value:,.2f}"


def create_investigation_summary(row, probability, threshold):
    # Transparent heuristic summary; this is not generated by an LLM.
    signals = []
    if row["type"] in ["TRANSFER", "CASH_OUT"]:
        signals.append(
            f"Transaction type is {row['type']}, which contains the fraud cases "
            "observed in this PaySim dataset."
        )
    if row["amount"] >= 1_000_000:
        signals.append("Transaction amount is at least 1,000,000 dataset currency units.")
    if row["oldbalanceOrg"] > 0 and row["amount"] >= 0.8 * row["oldbalanceOrg"]:
        signals.append(
            "Transaction amount is large relative to the sender's pre-transaction balance."
        )
    if row["oldbalanceDest"] == 0:
        signals.append("Destination's recorded pre-transaction balance is zero.")
    if not signals:
        signals.append(
            "No simple rule-based signals were triggered; review the model probability "
            "and transaction context."
        )

    decision = "FLAG FOR REVIEW" if probability >= threshold else "NOT FLAGGED"
    risk = "HIGH" if probability >= 0.80 else "MEDIUM" if probability >= 0.40 else "LOW"

    summary = (
        f"Model-estimated fraud probability: {probability:.2%}. "
        f"Configured decision threshold: {threshold:.2f}. "
        f"Decision: {decision}. Illustrative risk band: {risk}.\n\n"
        "Observed indicators:\n- " + "\n- ".join(signals) +
        "\n\nThis is a decision-support explanation, not proof of fraud. "
        "The model was trained on synthetic PaySim data."
    )
    return risk, decision, summary


def save_alert(row, probability, threshold, risk, decision):
    with sqlite3.connect(DB_PATH) as conn:
        conn.execute(
            """
            INSERT INTO fraud_alerts
            (created_at, step, transaction_type, amount, oldbalance_org,
             oldbalance_dest, fraud_probability, threshold, risk_level, decision)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                datetime.now().isoformat(timespec="seconds"),
                int(row["step"]),
                str(row["type"]),
                float(row["amount"]),
                float(row["oldbalanceOrg"]),
                float(row["oldbalanceDest"]),
                float(probability),
                float(threshold),
                risk,
                decision,
            ),
        )
        conn.commit()


def read_alerts():
    with sqlite3.connect(DB_PATH) as conn:
        return pd.read_sql_query(
            "SELECT * FROM fraud_alerts ORDER BY alert_id DESC LIMIT 500", conn
        )


init_db()
model, config = load_model_and_config()
threshold = float(config.get("selected_threshold", 0.50)) if config else 0.50

st.title("🛡️ Financial Fraud Detection & Investigation")
st.caption(
    "Machine-learning decision support using PaySim synthetic transactions. "
    "Scores are not proof of fraud or validated banking performance."
)

if model is None:
    st.error(
        "Trained model not found. Run main.py first and confirm "
        "outputs/fraud_model.joblib exists."
    )
    st.stop()

data, type_summary, time_summary = load_dashboard_data()

tab1, tab2, tab3, tab4 = st.tabs(
    ["Overview", "Transaction Screening", "Investigation Alerts", "Model & Business Insights"]
)

with tab1:
    st.subheader("Portfolio overview")
    if data is None:
        st.warning("Dataset CSV not found in the data folder. Prediction still works.")
    else:
        total_tx = len(data)
        fraud_count = int(data["isFraud"].sum())
        legitimate_count = total_tx - fraud_count
        fraud_rate = fraud_count / total_tx * 100

        c1, c2, c3, c4 = st.columns(4)
        c1.metric("Total transactions", f"{total_tx:,}")
        c2.metric("Fraud cases", f"{fraud_count:,}")
        c3.metric("Legitimate transactions", f"{legitimate_count:,}")
        c4.metric("Fraud prevalence", f"{fraud_rate:.4f}%")

        left, right = st.columns(2)
        with left:
            fig = px.bar(
                type_summary.sort_values("fraud_cases", ascending=False),
                x="type", y="fraud_cases",
                title="Fraud cases by transaction type",
                labels={"type": "Transaction type", "fraud_cases": "Fraud cases"},
            )
            st.plotly_chart(fig, use_container_width=True)
        with right:
            fig = px.line(
                time_summary, x="step", y="transactions",
                title="Transaction volume over simulation time",
                labels={"step": "Simulation step", "transactions": "Transactions"},
            )
            st.plotly_chart(fig, use_container_width=True)

        fig = px.bar(
            type_summary, x="type", y="fraud_rate_pct",
            title="Fraud rate by transaction type (%)",
            labels={"type": "Transaction type", "fraud_rate_pct": "Fraud rate (%)"},
        )
        st.plotly_chart(fig, use_container_width=True)

with tab2:
    st.subheader("Screen an individual transaction")
    st.write(
        "Enter pre-transaction information. The model uses the same five features "
        "used during training."
    )
    with st.form("transaction_form"):
        col1, col2, col3 = st.columns(3)
        with col1:
            step = st.number_input("Simulation step", min_value=1, max_value=1000, value=414)
            transaction_type = st.selectbox("Transaction type", TRANSACTION_TYPES, index=2)
        with col2:
            amount = st.number_input("Transaction amount", min_value=0.0, value=250000.0, step=1000.0)
            oldbalance_org = st.number_input("Sender's old balance", min_value=0.0, value=300000.0, step=1000.0)
        with col3:
            oldbalance_dest = st.number_input("Receiver's old balance", min_value=0.0, value=50000.0, step=1000.0)
            st.caption(f"Current threshold: **{threshold:.2f}**")
        submitted = st.form_submit_button("Analyse transaction", type="primary")

    if submitted:
        input_row = pd.DataFrame([{
            "step": int(step),
            "type": transaction_type,
            "amount": float(amount),
            "oldbalanceOrg": float(oldbalance_org),
            "oldbalanceDest": float(oldbalance_dest),
        }], columns=FEATURES)

        probability = float(model.predict_proba(input_row)[0, 1])
        risk, decision, summary = create_investigation_summary(
            input_row.iloc[0], probability, threshold
        )

        st.session_state["last_screening"] = {
            "row": input_row.iloc[0].to_dict(),
            "probability": probability,
            "risk": risk,
            "decision": decision,
            "summary": summary,
        }

    if "last_screening" in st.session_state:
        result = st.session_state["last_screening"]
        a, b, c = st.columns(3)
        a.metric("Estimated fraud probability", f"{result['probability']:.2%}")
        b.metric("Illustrative risk band", result["risk"])
        c.metric("Screening decision", result["decision"])

        st.progress(min(max(result["probability"], 0.0), 1.0))
        st.markdown("**Investigation assistant — rule-based summary**")
        st.info(result["summary"])

        if st.button("Save this screening to investigation database"):
            save_alert(
                pd.Series(result["row"]),
                result["probability"],
                threshold,
                result["risk"],
                result["decision"],
            )
            st.success("Screening saved to the local SQLite investigation database.")

with tab3:
    st.subheader("Investigation alert register")
    alerts = read_alerts()
    if alerts.empty:
        st.info("No screenings saved yet. Use Transaction Screening to create an alert.")
    else:
        st.metric("Saved screenings (latest 500)", len(alerts))
        st.dataframe(alerts, use_container_width=True, hide_index=True)
        csv = alerts.to_csv(index=False).encode("utf-8")
        st.download_button(
            "Download alert register as CSV",
            data=csv,
            file_name="fraud_investigation_alerts.csv",
            mime="text/csv",
        )

with tab4:
    st.subheader("Model performance and business trade-offs")
    if config:
        c1, c2, c3 = st.columns(3)
        c1.metric("Selected threshold", f"{threshold:.2f}")
        c2.metric("Evaluation precision", f"{config.get('evaluation_precision', 0):.2%}")
        c3.metric("Evaluation recall", f"{config.get('evaluation_recall', 0):.2%}")
        st.caption(config.get("selection_method", "Threshold configuration loaded from main.py."))
    else:
        st.warning("Threshold configuration not found; using default threshold 0.50.")

    comparison_path = OUTPUT_DIR / "threshold_evaluation_comparison.csv"
    if comparison_path.exists():
        comparison = pd.read_csv(comparison_path)
        st.dataframe(comparison, use_container_width=True, hide_index=True)
        st.caption(
            "Threshold selection is a candidate decision setting. Review false negatives "
            "and alert capacity before operational use."
        )

    shap_path = OUTPUT_DIR / "shap_feature_importance.csv"
    if shap_path.exists():
        shap_df = pd.read_csv(shap_path).head(10)
        if {"Feature", "Mean_Absolute_SHAP"}.issubset(shap_df.columns):
            fig = px.bar(
                shap_df.sort_values("Mean_Absolute_SHAP"),
                x="Mean_Absolute_SHAP", y="Feature", orientation="h",
                title="Global feature importance (mean absolute SHAP)",
            )
            st.plotly_chart(fig, use_container_width=True)

    network_path = OUTPUT_DIR / "account_network_analysis.csv"
    if network_path.exists():
        st.markdown("**Sampled account activity analysis**")
        network_df = pd.read_csv(network_path)
        st.dataframe(network_df.head(10), use_container_width=True, hide_index=True)
        st.caption(
            "Network ranking reflects sampled transaction activity, not confirmed fraud."
        )

st.divider()
st.caption(
    "Prototype limitations: PaySim is synthetic; SQLite is local demonstration storage; "
    "the investigation narrative is rule-based and does not call an external LLM."
)